<?php
namespace App\Http\Middleware;
use Closure; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\Response;
class SecurityHeaders {public function handle(Request $request,Closure $next):Response{$r=$next($request);$r->headers->set('X-Content-Type-Options','nosniff');$r->headers->set('X-Frame-Options','DENY');$r->headers->set('Referrer-Policy','strict-origin-when-cross-origin');$r->headers->set('Permissions-Policy','camera=(), microphone=(), geolocation=()');$r->headers->set('Content-Security-Policy',"default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'");if(app()->environment('production')&&$request->isSecure())$r->headers->set('Strict-Transport-Security','max-age=31536000; includeSubDomains');return $r;}}
